const AKBAR_INFO={id:"akbar-ilahi-coinage",title:"Akbar's Ilahi Coinage & Monetary Reforms",ruler:"Jalal-ud-din Muhammad Akbar (3rd Mughal Emperor)",reignPeriod:"1556 – 1605 CE (963–1014 AH)",ilahiEraStart:"1556 CE (Ilahi Year 1 = Accession at Kalanaur)",reformYear:"1585 CE (30th Regnal Year / 993 AH)",motto:"الله أكبر جل جلاله (Allahu Akbar Jalla Jalalahu)",primaryMints:"Agra, Fatehpur Sikri, Lahore, Ahmedabad, Patna, Delhi",quickStats:[{label:"Reform Year",value:"1585 CE (RY 30)",icon:"📜"},{label:"Calendar System",value:"Solar Ilahi Era",icon:"☀️"},{label:"Universal Motto",value:"Allahu Akbar",icon:"✨"},{label:"Popular Shape",value:"Square Jalali",icon:"⏹️"},{label:"Imperial Mints",value:"6 Major Mints",icon:"🏛️"},{label:"Denominations",value:"Mohur, Rupee, Dam",icon:"🪙"}]},COIN_TYPES=[{id:"square-jalali",name:"Square Silver Jalali Rupee",mint:"Fatehpur Sikri & Agra",metal:"Silver (11.4 grams)",shape:"Square (Jalali format)",obverseText:"الله أكبر (Allahu Akbar)",reverseText:"جل جلاله (Jalla Jalalahu) + Ilahi Month (Farwardin) & Year (RY 32)",significance:"The iconic square rupee introduced by Akbar to signify absolute metallic purity and distinction from earlier Islamic coinages.",imageObverse:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Akbar_Square_Rupee.jpg/600px-Akbar_Square_Rupee.jpg"},{id:"round-ilahi-mohur",name:"Round Gold Ilahi Mohur",mint:"Agra Mint",metal:"Gold (10.9 grams, 0.990 fineness)",shape:"Round",obverseText:"الله أكبر جل جلاله (Allahu Akbar Jalla Jalalahu)",reverseText:"Zarb Agra - Mah Mihr Ilahi 43 (Minted at Agra in Month of Mihr, Year 43)",significance:"High-purity imperial gold currency distributed during royal court ceremonies (Durbar).",imageObverse:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Akbar_Gold_Mohur.jpg/600px-Akbar_Gold_Mohur.jpg"},{id:"mihrabi-mohur",name:"Mihrabi Gold Mohur (Arched Niche)",mint:"Agra / Imperial Camp (Urdu Zafar Qarin)",metal:"Gold (10.8 grams)",shape:"Mihrabi (Hexagonal Arch / Prayer Niche Shape)",obverseText:"Allahu Akbar",reverseText:"Jalla Jalalahu + Mint of Imperial Camp",significance:"An artistic marvel minted in the shape of a mosque prayer arch (Mihrab).",imageObverse:"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Akbar_Mihrabi_Mohur.jpg/600px-Akbar_Mihrabi_Mohur.jpg"}],ILAHI_MONTHS=[{name:"Farwardin",gregorianEquivalent:"March – April",season:"Spring (Nowruz)"},{name:"Urdibihisht",gregorianEquivalent:"April – May",season:"Late Spring"},{name:"Khurdad",gregorianEquivalent:"May – June",season:"Early Summer"},{name:"Tir",gregorianEquivalent:"June – July",season:"Summer / Monsoon"},{name:"Amardad",gregorianEquivalent:"July – August",season:"Mid Monsoon"},{name:"Shahriwar",gregorianEquivalent:"August – September",season:"Harvest Season"},{name:"Mihr",gregorianEquivalent:"September – October",season:"Autumn Equinox"},{name:"Aban",gregorianEquivalent:"October – November",season:"Late Autumn"},{name:"Azar",gregorianEquivalent:"November – December",season:"Early Winter"},{name:"Dai",gregorianEquivalent:"December – January",season:"Winter Solstice"},{name:"Bahman",gregorianEquivalent:"January – February",season:"Mid Winter"},{name:"Isfandarmad",gregorianEquivalent:"February – March",season:"Late Winter"}],INSCRIPTION_HOTSPOTS=[{phrase:"الله أكبر (Allahu Akbar)",literalMeaning:"God is Great (or Akbar is of God)",context:"Universalist motto embodying Akbar's Din-i-Ilahi philosophy of divine unity (Sulh-i-Kul)."},{phrase:"جل جلاله (Jalla Jalalahu)",literalMeaning:"Glorious is His Glory",context:"The complementary phrase completing the Obverse & Reverse dual inscription."},{phrase:"Month & Regnal Year (e.g. Mah Mihr Ilahi 40)",literalMeaning:"Minted in the Solar Month of Mihr, 40th Year of Akbar's Reign",context:"Replaced lunar Hijri dates with precise solar calendar dates."}],TIMELINE_EVENTS=[{year:"1556 CE (1st Ilahi Year)",title:"Accession of Akbar",description:"Akbar ascends throne at Kalanaur, Punjab; this year is fixed as Epoch Year 1 of the Solar Ilahi Era."},{year:"1579 CE",title:"Mazhar Decree (Infallibility Decree)",description:"Akbar promulgates the Mazhar decree asserting supreme religious arbitration authority."},{year:"1585 CE (30th Regnal Year)",title:"Introduction of Ilahi Coinage",description:"Akbar officially replaces Hijri dates and Kalima with Solar Ilahi months and 'Allahu Akbar Jalla Jalalahu'."},{year:"1605 CE (50th Ilahi Year)",title:"Legacy & Final Mintage",description:"Ilahi coins minted until Akbar's death, establishing standard weight systems retained by future rulers."}],REFERENCES=[{text:"Abul Fazl (1598). Ain-i-Akbari (Institute of Akbar). Trans. H. Blochmann.",link:"#"},{text:"Brown, C. J. (1922). The Coins of India. Heritage Publishers.",link:"#"},{text:"Hodivala, S. H. (1923). Historical Studies in Mughal Numismatics. Numismatic Society of India.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={AKBAR_INFO:AKBAR_INFO,COIN_TYPES:COIN_TYPES,ILAHI_MONTHS:ILAHI_MONTHS,INSCRIPTION_HOTSPOTS:INSCRIPTION_HOTSPOTS,TIMELINE_EVENTS:TIMELINE_EVENTS,REFERENCES:REFERENCES});